#!/usr/bin/env node
// GUARD: does convex/_generated/api.d.ts describe the modules that actually
// exist in convex/?
//
// WHY THIS EXISTS. api.d.ts is generated by `npx convex dev`/`deploy`, which
// means it is ALWAYS correct on the machine that last ran one — and can be
// arbitrarily stale in the repo. Vercel never runs Convex codegen; it type
// checks the committed file. So the local gate and the deploy gate are reading
// different inputs, and `npx tsc --noEmit` can pass on a tree that cannot
// build.
//
// This has now cost real time twice, in opposite directions:
//
//   2026-08-03  api.d.ts AHEAD of its sources — named two modules that were
//               not in the repo. SILENT: skipLibCheck suppresses errors that
//               originate inside a .d.ts, so tsc, lint, tests and Vercel all
//               went green on a broken commit (7efaccb, still in master).
//   2026-08-11  api.d.ts BEHIND its sources — convex/documents.ts was
//               committed, api.d.ts was not. LOUD, but only on Vercel, where
//               `Property 'documents' does not exist` failed the build. Four
//               red deploys over six hours; Documents & Waivers was written up
//               as shipped and had never been live.
//
// See claude/typecheck-blind-spot-api-d-ts.md for the full post-mortem.
//
// WHY NOT `npx convex codegen && next build`, the obvious fix: codegen refuses
// to run without CONVEX_DEPLOYMENT and then makes a network call to the
// deployment. That is not something a production build should depend on, and a
// preview build could resolve it to the wrong deployment. Convex's own CLI help
// says to commit the file and use codegen "in CI to ensure the correct code was
// checked in" — a check, not a generate. This is that check, done offline with
// no CLI and no network: pure string comparison between a directory listing and
// a file.
//
// Runs from `npm run build`, so Vercel fails in milliseconds with an
// actionable message instead of a type error fifteen seconds in.

import { readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const convexDir = join(root, "convex");
const apiPath = join(convexDir, "_generated", "api.d.ts");

// Files under convex/ that are NOT pushed as function modules and so never
// appear in api.d.ts. Verified against the real tree on 2026-08-11: 32 modules
// listed, 32 files matched, zero drift either way.
//
//   *.test.ts       convex-test files, excluded by Convex itself
//   schema.ts       the schema, reached through dataModel.d.ts not api.d.ts
//   auth.config.ts  Clerk auth config, not a function module
//   tsconfig.json / README.md / _generated  not modules at all
//
// If Convex ever changes what it pushes, this list is the thing to update —
// and the failure mode is a loud false positive, not a silent miss.
const NOT_A_MODULE = new Set(["schema.ts", "auth.config.ts"]);

function isModuleFile(name) {
  if (!name.endsWith(".ts")) return false;
  if (name.endsWith(".test.ts")) return false;
  if (name.startsWith(".") || name.startsWith("_")) return false;
  return !NOT_A_MODULE.has(name);
}

function fail(lines) {
  console.error("");
  console.error("  convex/_generated/api.d.ts is out of sync with convex/");
  console.error("");
  for (const line of lines) console.error(`  ${line}`);
  console.error("");
  console.error("  Fix:");
  console.error("    npx convex dev --once            # regenerates api.d.ts");
  console.error("    git add convex/_generated/api.d.ts");
  console.error("");
  console.error("  Why you didn't see this locally: convex dev/deploy rewrite");
  console.error("  api.d.ts on your disk every run, so tsc reads a fresh copy");
  console.error("  while the build reads the committed one. See");
  console.error("  claude/typecheck-blind-spot-api-d-ts.md");
  console.error("");
  process.exit(1);
}

let onDisk;
let api;
try {
  onDisk = new Set(
    readdirSync(convexDir, { withFileTypes: true })
      .filter((e) => e.isFile() && isModuleFile(e.name))
      .map((e) => e.name.slice(0, -3))
  );
  api = readFileSync(apiPath, "utf8");
} catch (err) {
  // Deliberately NOT a failure. This guard blocks production deploys, so an
  // unexpected environment (a partial checkout, a moved directory) must not be
  // what takes the site down. The mismatch it was written to catch is precise
  // and well understood; anything else gets a warning and a pass.
  console.warn(`  [check-convex-api] skipped: ${err.message}`);
  process.exit(0);
}

// Both halves of the generated file are checked, not just the imports: they are
// written together but a hand-edit or a bad merge can touch one and not the
// other, and the fullApi block is the half that actually types `api.*`.
const imported = new Set([...api.matchAll(/import type \* as (\w+) from "\.\.\//g)].map((m) => m[1]));
const inFullApi = new Set([...api.matchAll(/^\s{2}(\w+): typeof \1;$/gm)].map((m) => m[1]));

if (imported.size === 0) {
  console.warn("  [check-convex-api] skipped: no module imports found — generator format may have changed");
  process.exit(0);
}

const missing = [...onDisk].filter((m) => !imported.has(m)).sort();
const orphaned = [...imported].filter((m) => !onDisk.has(m)).sort();
const halvesDisagree = [...imported].filter((m) => !inFullApi.has(m)).sort();

const problems = [];
if (missing.length) {
  problems.push(
    `MISSING from api.d.ts (file exists, api.d.ts doesn't know): ${missing.join(", ")}`,
    "  -> the build will fail with \"Property '<name>' does not exist\"."
  );
}
if (orphaned.length) {
  problems.push(
    `ORPHANED in api.d.ts (named, but no such file): ${orphaned.join(", ")}`,
    "  -> this one is SILENT under skipLibCheck. Types degrade, nothing errors.",
    "  -> check the module is committed: git ls-files convex/"
  );
}
if (halvesDisagree.length) {
  problems.push(
    `Imported but absent from the fullApi block: ${halvesDisagree.join(", ")}`,
    "  -> api.d.ts was hand-edited or badly merged. Regenerate it."
  );
}

if (problems.length) fail(problems);

console.log(`  [check-convex-api] ok — ${onDisk.size} modules, api.d.ts agrees`);
